update public.chambers set pupillage_overview='One Essex Court recruits pupils through the Pupillage Gateway. Pupils sit with three supervisors and receive a £90,000 award, comprising a £60,000 first-six scholarship and a £30,000 second-six award, while retaining second-six earnings. Up to £30,000 may be advanced during the Bar Practice Course year. All pupils who meet the required standard are offered tenancy.',mini_pupillage_overview='One Essex Court does not offer direct commercial mini-pupillages. Applications for its separate intellectual-property mini-pupillage are on hold. It instead runs open evenings and participates in access schemes including Bridging the Bar.',tenancy_overview='Pupillage is offered with a view to tenancy. Established-practitioner and lateral recruitment are excluded from Vacatory.',pupillage_gateway_member=true,pupillage_gateway_url='https://www.pupillagegateway.com/',research_status='verified',research_checked_on=date '2026-10-15',next_review_on=date '2026-11-02',updated_at=now() where organisation_id='4d88055b-f3d8-41ab-a009-6de45b57b928';
insert into public.career_opportunities(organisation_id,opportunity_type_id,slug,official_name,public_name,public_summary,delivery_mode,official_url,application_url,active,published,research_checked_on,next_review_on) select '4d88055b-f3d8-41ab-a009-6de45b57b928','06f22221-7e57-4379-b2a1-fcbec5d4f4bb','one-essex-court-10000-black-interns-bar-2027','10,000 Black Interns — The Bar 2027 — One Essex Court Participant','10,000 Black Interns — The Bar 2027 — One Essex Court Participant','Paid Bar workstream for eligible Black students and recent graduates. One Essex Court confirms participation; host allocation is managed by the programme and is not guaranteed.','in_person','https://www.oeclaw.co.uk/join-us/commitment-to-equality-and-diversity','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,true,date '2026-10-15',date '2026-11-02' where not exists(select 1 from public.career_opportunities where slug='one-essex-court-10000-black-interns-bar-2027');
insert into public.career_opportunity_cycles(opportunity_id,cycle_key,cycle_label,application_year,programme_year,intake_year,application_model,opens_on,closes_on,application_dates_text,programme_dates_text,date_precision,duration_text,source_status,audience_text,eligibility_text,official_url,application_url,active,research_checked_on) select id,'one-essex-court-10000-black-interns-bar-2027',official_name,2026,2027,2027,'fixed_deadline',date '2026-10-05',date '2026-11-01','Applications close on 1 November 2026.','Paid internships take place between May and September 2027; dates vary by host.','exact','At least six weeks','open','Eligible Black students and recent graduates interested in the Bar.','Applicants must meet the Foundation’s ethnicity, age, UK study or recent-graduate, previous-participation and right-to-work requirements.','https://www.oeclaw.co.uk/join-us/commitment-to-equality-and-diversity','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,date '2026-10-15' from public.career_opportunities where slug='one-essex-court-10000-black-interns-bar-2027' and not exists(select 1 from public.career_opportunity_cycles c where c.opportunity_id=career_opportunities.id);
insert into public.career_opportunities(organisation_id,opportunity_type_id,slug,official_name,public_name,public_summary,delivery_mode,official_url,application_url,active,published,research_checked_on,next_review_on) select '4d88055b-f3d8-41ab-a009-6de45b57b928','45e6b1b6-6589-4e4f-b6b7-7cf2ddc28a89','one-essex-court-bridging-the-bar-academy-2027-28','Bridging the Bar Academy 2027/28 — One Essex Court Partner','Bridging the Bar Academy 2027/28 — One Essex Court Partner','Access programme providing mentoring, advocacy and application training and at least one mini-pupillage through participating chambers, including One Essex Court. Placement with a particular chambers is not guaranteed.','hybrid','https://www.oeclaw.co.uk/join-us/mentoring-and-other-opportunities','https://bridgingthebar.org/academy-applications/',true,true,date '2026-10-15',date '2026-11-06' where not exists(select 1 from public.career_opportunities where slug='one-essex-court-bridging-the-bar-academy-2027-28');
insert into public.career_opportunity_cycles(opportunity_id,cycle_key,cycle_label,application_year,programme_year,intake_year,application_model,opens_on,closes_on,closes_at,closes_timezone,application_dates_text,programme_dates_text,date_precision,duration_text,source_status,study_stage_text,eligibility_text,official_url,application_url,active,research_checked_on) select id,'one-essex-court-bridging-the-bar-academy-2027-28',official_name,2026,2027,2027,'fixed_deadline',date '2026-10-02',date '2026-11-05',time '17:00','Europe/London','Applications close at 17:00 on 5 November 2026.','The Academy runs from August 2027 to June 2028.','exact','August 2027 to June 2028','open','Bar Course student in 2027–28 or Bar Course graduate intending to apply for pupillage in 2028.','Applicants must meet the Academy’s published education and financial-support criteria and be available in the United Kingdom for programme activity.','https://www.oeclaw.co.uk/join-us/mentoring-and-other-opportunities','https://bridgingthebar.org/academy-applications/',true,date '2026-10-15' from public.career_opportunities where slug='one-essex-court-bridging-the-bar-academy-2027-28' and not exists(select 1 from public.career_opportunity_cycles c where c.opportunity_id=career_opportunities.id);
delete from public.career_opportunity_routes where route_kind='unresolved' and opportunity_id in(select id from public.career_opportunities where slug in ('one-essex-court-10000-black-interns-bar-2027','one-essex-court-bridging-the-bar-academy-2027-28'));
insert into public.career_opportunity_routes(opportunity_id,route_kind,country_id,city_id,route_note,route_status,display_order,active) select id,'physical_city',47,139,'London / programme-managed placement','confirmed',10,true from public.career_opportunities o where slug in ('one-essex-court-10000-black-interns-bar-2027','one-essex-court-bridging-the-bar-academy-2027-28') and not exists(select 1 from public.career_opportunity_routes r where r.opportunity_id=o.id and r.city_id=139);
